head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.ProcsStatCd = ""; // 처리상태코드(34:수정요청)
scwin.fr_SecuGrpId = ""; // 신탁수익증권(TC), 투자계약증권(IC)
// 상장관련공통함수
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.TR_JOB;
scwin.procJob;
scwin.vCurDate;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

        // 분배금 지급일 텍스트박스 숨기기

        txb_DISTR_PAY_BAS_DD1.hide();
        txb_DISTR_PAY_BAS_DD2.hide();
        txb_DISTR_PAY_BAS_DD3.hide();
        txb_DISTR_PAY_BAS_DD4.hide();
        txb_DISTR_PAY_BAS_DD5.hide();
        txb_DISTR_PAY_BAS_DD6.hide();
        txb_DISTR_PAY_BAS_DD7.hide();
        txb_DISTR_PAY_BAS_DD8.hide();
        txb_DISTR_PAY_BAS_DD9.hide();
        txb_DISTR_PAY_BAS_DD10.hide();
        txb_DISTR_PAY_BAS_DD11.hide();
        txb_DISTR_PAY_BAS_DD12.hide();
        await scwin.searchCode(); // 기초자산, 분배금형태
        await scwin.searchLPCode(); // 유동성공급자 조회
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70031.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70031.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70031.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        scwin.fr_SecuGrpId = dts_Isu.getCellData(1, "SECUGRP_ID");
        scwin.ProcsStatCd = dts_Isu.getCellData(1, "PROCS_STAT_CD");
        if (scwin.ProcsStatCd === "34") {
            // 수정요청
            /*
            btn_update.value = "수정요청중";
            btn_update.disabled = true;
             */
            btn_update.setBackgroundImage("../img/btn_upreq_d.gif");
            btn_update.setDisabled(true);
            btn_update.style.width = 80;
            btn_update.style.left = 1114;
        } else {
            /*
            btn_update.value = "수정요청";
            btn_update.disabled = false;
             */
            btn_update.setBackgroundImage("../img/btn_upreq.gif");
            btn_update.setDisabled(false);
            btn_update.style.width = 60;
            btn_update.style.left = 1134;
        }

        // 신탁수익증권(TC)의 경우 신탁기관 법인명 수정가능 / 투자계약증권(IC)의 경우, 위탁/보관기관명 수정가능
        if (scwin.fr_SecuGrpId === "TC") {
            // 신탁기관 관련 항목들 수정가능
            // txb_TRST_INST_ISUR_CD.readOnly = false;
            img_TRST_INST_ISUR.readOnly = false;
            img_TRST_INST_ISUR.setDisabled(false);
            txb_TRST_INST_ISUR_NM.setReadOnly(false);
            txb_TRST_CONTRT_PD_STRT_DD.setReadOnly(false);
            img_TRST_CONTRT_PD_STRT_DD.readOnly = false;
            img_TRST_CONTRT_PD_STRT_DD.setDisabled(false);
            txb_TRST_CONTRT_PD_END_DD.setReadOnly(false);
            img_TRST_CONTRT_PD_END_DD.readOnly = false;
            img_TRST_CONTRT_PD_END_DD.setDisabled(false);

            // txb_DESIGN_ADVSER_CONTRT_STRT_DD.readOnly = true;  //지정자문인 계약기간 start
            // txb_DESIGN_ADVSER_CONTRT_END_DD.readOnly = true;  //지정자문인 계약기간 end

            txb_DESIGN_ADVSER_CHRG_NM.setReadOnly(true); // 기타사항 지정자문인 담당자
            txb_DESIGN_ADVSER_CHRG_TEL_NO.setReadOnly(true); // 기타사항 지정자문인 담당자 연락처
            txb_DESIGN_ADVSER_CHRG_NM.style.backgroundColor = '#b9d4f7';
            txb_DESIGN_ADVSER_CHRG_TEL_NO.style.backgroundColor = '#b9d4f7';

            // txb_TRST_INST_ISUR_CD.style.backgroundColor = '#FFFFFF';
            img_TRST_INST_ISUR.setBackgroundImage("../img/btn_search.gif");
            txb_TRST_INST_ISUR_NM.style.backgroundColor = '#FFFFFF';
            txb_TRST_CONTRT_PD_STRT_DD.style.backgroundColor = '#FFFFFF';
            img_TRST_CONTRT_PD_STRT_DD.src = "../img/icn_calendar.gif";
            txb_TRST_CONTRT_PD_END_DD.style.backgroundColor = '#FFFFFF';
            img_TRST_CONTRT_PD_END_DD.src = "../img/icn_calendar.gif";

            // 위탁기관 관련 항목들 수정불가능
            txb_TRST_CUSTDN_NM.setReadOnly(true);
            txb_TRST_CUSTDN_STRT_DD.setReadOnly(true);
            img_TRST_CUSTDN_STRT_DD.readOnly = true;
            img_TRST_CUSTDN_STRT_DD.setDisabled(true);
            txb_TRST_CUSTDN_END_DD.setReadOnly(true);
            img_TRST_CUSTDN_END_DD.readOnly = true;
            img_TRST_CUSTDN_END_DD.setDisabled(true);
            txb_TRST_CUSTDN_NM.style.backgroundColor = '#b9d4f7';
            txb_TRST_CUSTDN_STRT_DD.style.backgroundColor = '#b9d4f7';
            img_TRST_CUSTDN_STRT_DD.src = "../img/icn_calendar_d.gif";
            txb_TRST_CUSTDN_END_DD.style.backgroundColor = '#b9d4f7';
            img_TRST_CUSTDN_END_DD.src = "../img/icn_calendar_d.gif";
        } else {
            // 신탁기관 관련 항목들 수정불가능
            // txb_TRST_INST_ISUR_CD.readOnly = true;
            // txb_TRST_INST_ISUR_CD.style.backgroundColor = '#b9d4f7';
            img_TRST_INST_ISUR.readOnly = true;
            img_TRST_INST_ISUR.setDisabled(true);
            img_TRST_INST_ISUR.setBackgroundImage("../img/btn_search_d.gif");
            txb_TRST_INST_ISUR_NM.setReadOnly(true);
            txb_TRST_INST_ISUR_NM.style.backgroundColor = '#b9d4f7';
            txb_TRST_CONTRT_PD_STRT_DD.setReadOnly(true);
            txb_TRST_CONTRT_PD_STRT_DD.style.backgroundColor = '#b9d4f7';
            img_TRST_CONTRT_PD_STRT_DD.readOnly = true;
            img_TRST_CONTRT_PD_STRT_DD.setDisabled(true);
            img_TRST_CONTRT_PD_STRT_DD.src = "../img/icn_calendar_d.gif";
            txb_TRST_CONTRT_PD_END_DD.setReadOnly(true);
            txb_TRST_CONTRT_PD_END_DD.style.backgroundColor = '#b9d4f7';
            img_TRST_CONTRT_PD_END_DD.readOnly = true;
            img_TRST_CONTRT_PD_END_DD.setDisabled(true);
            img_TRST_CONTRT_PD_END_DD.src = "../img/icn_calendar_d.gif";

            // txb_DESIGN_ADVSER_CONTRT_STRT_DD.readOnly = false;  //지정자문인 계약기간 start
            // txb_DESIGN_ADVSER_CONTRT_END_DD.readOnly = false;  //지정자문인 계약기간 end
            // img_DESIGN_ADVSER_CONTRT_STRT_DD.src = "../img/icn_calendar.gif";

            txb_DESIGN_ADVSER_CHRG_NM.setReadOnly(false); // 기타사항 지정자문인 담당자
            txb_DESIGN_ADVSER_CHRG_TEL_NO.setReadOnly(false); // 기타사항 지정자문인 담당자 연락처
            txb_DESIGN_ADVSER_CHRG_NM.style.backgroundColor = '#FFFFFF';
            txb_DESIGN_ADVSER_CHRG_TEL_NO.style.backgroundColor = '#FFFFFF';

            // 위탁기관 관련 항목들 수정가능
            txb_TRST_CUSTDN_NM.setReadOnly(false);
            txb_TRST_CUSTDN_STRT_DD.setReadOnly(false);
            img_TRST_CUSTDN_STRT_DD.readOnly = false;
            img_TRST_CUSTDN_STRT_DD.setDisabled(false);
            txb_TRST_CUSTDN_END_DD.setReadOnly(false);
            img_TRST_CUSTDN_END_DD.readOnly = false;
            img_TRST_CUSTDN_END_DD.setDisabled(false);
            txb_TRST_CUSTDN_NM.style.backgroundColor = '#FFFFFF';
            txb_TRST_CUSTDN_STRT_DD.style.backgroundColor = '#FFFFFF';
            txb_TRST_CUSTDN_END_DD.style.backgroundColor = '#FFFFFF';
            img_TRST_CUSTDN_STRT_DD.src = "../img/icn_calendar.gif";
            img_TRST_CUSTDN_END_DD.src = "../img/icn_calendar.gif";
        }
        cmb_LP_MBR_NO1.setValue("");
        cmb_LP_MBR_NO2.setValue("");
        cmb_LP_MBR_NO3.setValue("");

        // 만기유무가 y 가 아닐 경우 최종거래일 enable 처리
        const vBasExpYn = dts_Isu.getCellData(1, "BAS_EXP_YN");
        if (vBasExpYn !== "Y") {
            txb_LSTTRD_DD.setReadOnly(true);
            img_LSTTRD_DD.readOnly = true;
            img_LSTTRD_DD.setDisabled(true);
            img_LSTTRD_DD.src = "../img/icn_calendar_d.gif";
        } else {
            txb_LSTTRD_DD.setReadOnly(false);
            img_LSTTRD_DD.readOnly = false;
            img_LSTTRD_DD.setDisabled(false);
            img_LSTTRD_DD.src = "../img/icn_calendar.gif";
        }

        // 분배금지급 기준일 활성화 처리
        let vDigitalDistrTp = false;
        // 분배금 형태가 지급일 경우
        if (cmb_DIGITAL_SECU_DISTR_TP_CD.getValue() === '02') {
            vDigitalDistrTp = true;
        }

        // 분배금 형태 가 미지급이거나 값이 없을  경우 기준일 1~12 비활성화
        // 분배금 형태가 지급일 경우 기준일 1~12 활성화
        for (let i = 1; i <= 12; i++) {
            getElementById('cmb_DISTR_PAY_BAS_M' + i).setDisabled(true);
            getElementById('cmb_DISTR_PAY_BAS_D' + i).setDisabled(true);
        }

        // fn_searchLPCode();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70031.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70031.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
        await scwin.getBaseInfoReadSync();
        // frame.CloseFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70031.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_SearchIsu_onclick
 * @description img_SearchIsu 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SearchIsu_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        $c.lcd.fn_PopFindDigitalIsuAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70031.img_SearchIsu_onclick" });
    }
};

