/**
 * @method
 * @name cmb_DUTY_HD_CMIT_YN_onselchange
 * @description cmb_DUTY_HD_CMIT_YN onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DUTY_HD_CMIT_YN_onselchange = function() {
    try {
        if (cmb_DUTY_HD_CMIT_YN.getValue() === "Y") {
            // 의무보유확약여부 Y일경우
            // 관련 component readonly 해제
            txb_DUTY_HD_NM.setReadOnly(false);
            txb_DUTY_HD_CNT.setReadOnly(false);
            txb_DUTY_HD_STRT_DD.setReadOnly(false);
            txb_DUTY_HD_END_DD.setReadOnly(false);
            txb_DUTY_HD_RELEAS_DD.setReadOnly(false);
            txb_DUTY_HD_NM.style.backgroundColor = '#FFFFFF';
            img_DUTY_HD_STRT_DD.setDisabled(false);
            img_DUTY_HD_END_DD.setDisabled(false);
            img_DUTY_HD_RELEAS_DD.setDisabled(false);
