 * @name cmb_DIGITAL_SECU_DISTR_TP_CD_onselchange
 * @description cmb_DIGITAL_SECU_DISTR_TP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DIGITAL_SECU_DISTR_TP_CD_onselchange = function() {
    try {
        // 분배금지급 기준일 활성화 처리
        let vDigitalDistrTp = false;
        // 분배금 형태가 지급일 경우
        if (cmb_DIGITAL_SECU_DISTR_TP_CD.getValue() === '02') {
            vDigitalDistrTp = true;
        }

        // 분배금 형태 가 미지급이거나 값이 없을  경우 기준일 1~12 비활성화
        // 분배금 형태가 지급일 경우 기준일 1~12 활성화
        for (let i = 1; i <= 12; i++) {
            getElementById('cmb_DISTR_PAY_BAS_M' + i).setDisabled(true);
            getElementById('cmb_DISTR_PAY_BAS_D' + i).setDisabled(true);

            // 미지급이라면 이전 값 없애기
            if (vDigitalDistrTp === false) {
                getElementById('cmb_DISTR_PAY_BAS_M' + i).setValue("");
                getElementById('cmb_DISTR_PAY_BAS_D' + i).setValue("");
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70031.cmb_DIGITAL_SECU_DISTR_TP_CD_onselchange" });
    }
};

