/**
 * @method
 * @name searchCode
 * @description 기초자산, 분배금형태코드 불러오기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    03685	DIGITAL_SECU_ULY_CD							기초자산
    03698	DIGITAL_SECU_DISTR_TP_CD			분배금형태코드
     */

    const arrCid = [{
        cid: "DIGITAL_SECU_ULY_CD",
        cnm: "cmb_DIGITAL_SECU_ULY_CD"
    }, {
        cid: "DIGITAL_SECU_DISTR_TP_CD",
        cnm: "cmb_DIGITAL_SECU_DISTR_TP_CD"
    }, {
        cid: "TAX_TP_CD",
        cnm: "cmb_TAX_TP_CD"
    }];
    let objCod;
    url += "&CD_ID_M='DIGITAL_SECU_ULY_CD','DIGITAL_SECU_DISTR_TP_CD','TAX_TP_CD'";
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                // 기초자산 "없음" 공백값 추가
                if (j === 1 && arrCid[i].cid === "DIGITAL_SECU_ULY_CD") {
                    strCbd = "^없음";
                }
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                // alert(strCbd);

            }
        }
        objCod.CBData = strCbd;
    }
};

