/**
 * @method
 * @name update
 * @description update 요청
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        if ($c.cp.isModified(dts_Isu) === false) {
            await $c.win.alert("수정내역이 존재하지 않습니다.");
            return;
        }
        scwin.TR_JOB = "U";
        if (!confirm('수정요청 하시겠습니까?') === true) {
            return;
        }
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
            return;
        }
        if ($c.cp.isModified(dts_Isu) === false) {
            await $c.win.alert("수정 요청내역이 존재하지 않습니다.");
            return;
        }
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TR_JOB_INSERT,
        //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
        //     BZ_PROCS_NO : scwin.vBzProcsNo,
        //     ISU_CD : $c.stf.getObjectValue(txb_SearchIsuCd),
        //     ISUR_CD : $c.stf.getObjectValue(txb_LIST_APPLNT_ISUR_CD),
        //     ACPT_NO : js_emp_no,
        //     LD_MKT_TP_CD : "1",
        //     TRANSTR_EMP_NO : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/digital/DigitalListinvstg.do",
            ref : "dts_Isu",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

