/**
 * @method
 * @name checkForm
 * @description 필수값 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    // 필수값
    // 기초자산

    // 기초자산 종류를 입력하였을 경우, 기초자산명이 공백값이면 필수
    // 기초자산 종류가 없을 경우 기초자산명 입력X
    if ((cmb_DIGITAL_SECU_ULY_CD.getValue() !== "") && txb_DIGITAL_SECU_ULY_NM.getValue() === "") {
        await $c.win.alert("[기초자산] 명을 입력하세요.");
        txb_DIGITAL_SECU_ULY_NM.focus();
        return;
    }
    // 신탁기관발행기관코드
    if ((txb_TRST_INST_ISUR_CD.getValue() !== "") && (txb_TRST_CONTRT_PD_STRT_DD.getValue() === "")) {
        await $c.win.alert("[신탁기관 계약기간] 시작일을 입력하세요.");
        txb_TRST_CONTRT_PD_STRT_DD.focus();
        return;
    }
    if ((txb_TRST_CONTRT_PD_STRT_DD.getValue() !== '') && (txb_TRST_CONTRT_PD_END_DD.getValue() !== '')) {
        if (txb_TRST_CONTRT_PD_STRT_DD.getValue() > txb_TRST_CONTRT_PD_END_DD.getValue()) {
            await $c.win.alert("[신탁기관 계약기간] 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }
    // 위탁/보관기관 계약기간
    if ((txb_TRST_CUSTDN_STRT_DD.getValue() !== '') && (txb_TRST_CUSTDN_END_DD.getValue() !== '')) {
        if (txb_TRST_CUSTDN_STRT_DD.getValue() > txb_TRST_CUSTDN_END_DD.getValue()) {
            await $c.win.alert("[위탁/보관기관 계약기간] 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }
    if (cmb_DUTY_HD_CMIT_YN.getValue() === "") {
        await $c.win.alert("[의무보유] 확약여부를 선택해주세요");
        cmb_DUTY_HD_CMIT_YN.focus();
        return;
    }

    // 의무보유 확약여부
    if (cmb_DUTY_HD_CMIT_YN.getValue() === "Y") {
        // 의무보유자
        if (txb_DUTY_HD_NM.getValue() === "") {
            await $c.win.alert("[의무보유] 의무보유자를 입력하세요.");
            txb_DUTY_HD_NM.focus();
            return;
        }
        // 의무보유수량
        if (txb_DUTY_HD_CNT.getValue() === "") {
            await $c.win.alert("[의무보유] 의무보유 수량을 입력하세요.");
            txb_DUTY_HD_CNT.focus();
            return;
        }
        // 의무보유기간 시작일
        if (txb_DUTY_HD_STRT_DD.getValue() === "") {
            await $c.win.alert("[의무보유기간] 시작일을 입력하세요.");
            txb_DUTY_HD_STRT_DD.focus();
            return;
        }
        // 의무보유기간 종료일
        if (txb_DUTY_HD_END_DD.getValue() === "") {
            await $c.win.alert("[의무보유기간] 종료일을 입력하세요.");
            txb_DUTY_HD_END_DD.focus();
            return;
        }
        if ((txb_DUTY_HD_STRT_DD.getValue() !== '') && (txb_DUTY_HD_END_DD.getValue() !== '')) {
            if (txb_DUTY_HD_STRT_DD.getValue() > txb_DUTY_HD_END_DD.getValue()) {
                await $c.win.alert("[의무보유기간] 시작일을 종료일 이전으로 선택하세요.");
                return false;
            }
        }
        // 의무보유해제일
        if (txb_DUTY_HD_RELEAS_DD.getValue() === "") {
            await $c.win.alert("[의무보유] 해제일을 입력하세요.");
            txb_DUTY_HD_RELEAS_DD.focus();
            return;
        }
    }

    // 유동성공급자계약체결여부
    if (cmb_LP_CONTRT_TRD_YN.getValue() === "") {
        await $c.win.alert("[유동성공급자계약] 체결여부를 선택하세요");
        cmb_LP_CONTRT_TRD_YN.focus();
        return;
    }
    // 유동성공급자계약체결여부 Y일 경우 '공급자' 한명이라도 입력되어야한다.
    if (cmb_LP_CONTRT_TRD_YN.getValue() === "Y") {
        if ((cmb_LP_MBR_NO1.getValue() === "") &&
            (cmb_LP_MBR_NO2.getValue() === "") &&
            (cmb_LP_MBR_NO3.getValue() === "")) {
            await $c.win.alert("[유동성공급자계약] 유동성공급자를 입력하세요.");
            return;
        }
        if ((cmb_LP_MBR_NO1.getValue() === "") &&
            ((cmb_LP_MBR_NO2.getValue() !== "") ||
                (cmb_LP_MBR_NO3.getValue() === ""))) {
            await $c.win.alert("[유동성공급자계약] 유동성공급자를 순서대로 입력하세요.");
            return;
        } else if (((cmb_LP_MBR_NO2.getValue() === "") || (cmb_LP_MBR_NO1.getValue() === "")) &&
            (cmb_LP_MBR_NO3.getValue() !== "")) {
            await $c.win.alert("[유동성공급자계약] 유동성공급자를 순서대로 입력하세요.");
            return;
        }
    }

    // 유동성공급자1 값이 있으면 시작기간 필수
    if ((cmb_LP_MBR_NO1.getValue() !== "") && (txb_LP_CONTRT_STRT_DD.getValue() === "")) {
        await $c.win.alert("[유동성공급자I] 계약기간 시작일을 입력하세요.");
        txb_LP_CONTRT_STRT_DD.focus();
        return;
    }
    if (((txb_LP_CONTRT_STRT_DD.getValue() !== "") || (txb_LP_CONTRT_END_DD.getValue() !== '')) && (cmb_LP_MBR_NO1.getValue() === "")) {
        await $c.win.alert("[유동성공급자I] 공급자를 선택하세요.");
        cmb_LP_MBR_NO1.focus();
        return;
    }
    if ((txb_LP_CONTRT_STRT_DD.getValue() !== '') && (txb_LP_CONTRT_END_DD.getValue() !== '')) {
        if (txb_LP_CONTRT_STRT_DD.getValue() > txb_LP_CONTRT_END_DD.getValue()) {
            await $c.win.alert("[유동성공급자I] 계약기간 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }

    // 유동성공급자2 값이 있으면 시작기간 필수
    if ((cmb_LP_MBR_NO2.getValue() !== "") && (txb_LP_CONTRT_STRT_DD2.getValue() === "")) {
        await $c.win.alert("[유동성공급자II] 계약기간 시작일을 입력하세요.");
        txb_LP_CONTRT_STRT_DD2.focus();
        return;
    }
    if (((txb_LP_CONTRT_STRT_DD2.getValue() !== "") || (txb_LP_CONTRT_END_DD2.getValue() !== '')) && (cmb_LP_MBR_NO2.getValue() === "")) {
        await $c.win.alert("[유동성공급자II] 공급자를 선택하세요.");
        cmb_LP_MBR_NO2.focus();
        return;
    }
    if ((txb_LP_CONTRT_STRT_DD2.getValue() !== '') && (txb_LP_CONTRT_END_DD2.getValue() !== '')) {
        if (txb_LP_CONTRT_STRT_DD2.getValue() > txb_LP_CONTRT_END_DD2.getValue()) {
            await $c.win.alert("[유동성공급자II] 계약기간 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }

    // 유동성공급자3 값이 있으면 시작기간 필수
    if ((cmb_LP_MBR_NO3.getValue() !== "") && (txb_LP_CONTRT_STRT_DD3.getValue() === "")) {
        await $c.win.alert("[유동성공급자III] 계약기간 시작일을 입력하세요.");
        txb_LP_CONTRT_STRT_DD3.focus();
        return;
    }
    if (((txb_LP_CONTRT_STRT_DD3.getValue() !== "") || (txb_LP_CONTRT_END_DD3.getValue() !== '')) && (cmb_LP_MBR_NO3.getValue() === "")) {
        await $c.win.alert("[유동성공급자III] 공급자를 선택하세요.");
        cmb_LP_MBR_NO3.focus();
        return;
    }
    if ((txb_LP_CONTRT_STRT_DD3.getValue() !== '') && (txb_LP_CONTRT_END_DD3.getValue() !== '')) {
        if (txb_LP_CONTRT_STRT_DD3.getValue() > txb_LP_CONTRT_END_DD3.getValue()) {
            await $c.win.alert("[유동성공급자III] 계약기간 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }

    // 만기유무
    /*if(mr_BAS_EXP_YN.CodeValue == ""){
    	alert("[만기 유무] YES/NO 선택하세요." );
    	mr_BAS_EXP_YN.focus();
    	return;
    }	*/

    if (mr_BAS_EXP_YN.getValue() === "Y") {
        if (txb_LSTTRD_DD.getValue() === "") {
            await $c.win.alert("[만기/중도상환에 관한 사항] 최종거래일을 입력하세요.");
            txb_LSTTRD_DD.focus();
            return;
        }
    }
    // 증권의 조기청산 가능여부
    if (mr_EARY_CLR_YN.getValue() === "") {
        await $c.win.alert("[증권의 조기청산 가능 여부] YES/NO 선택하세요.");
        mr_EARY_CLR_YN.focus();
        return;
    }
    // 상장여부
    /*if(mr_LIST_APPLNT_LIST_YN.CodeValue == ""){
    	alert("[상장 여부] YES/NO 선택하세요." );
    	mr_LIST_APPLNT_LIST_YN.focus();
    	return;
    }*/
    // 주식회사 여부
    if (mr_LIST_APPLNT_COLTD_YN.getValue() === "") {
        await $c.win.alert("[주식회사 여부] YES/NO 선택하세요.");
        mr_LIST_APPLNT_COLTD_YN.focus();
        return;
    }
    // 상장신청인 담당자명
    if (txb_LIST_APPL_CHRG_NM.getValue() === "") {
        await $c.win.alert("[상장신청인] 담당자명을 입력해주세요.");
        txb_LIST_APPL_CHRG_NM.focus();
        return;
    }
    // 상장신청인 담당자 연락처
    if (txb_LIST_APPL_CHRG_TEL_NO.getValue() === "") {
        await $c.win.alert("[상장신청인] 담당자 연락처를 입력해주세요.");
        txb_LIST_APPL_CHRG_TEL_NO.focus();
        return;
    }

    // 분배금 지급일 체크
    if (await scwin.checkDISTRPAY() === false) {
        return;
    }

    // 길이체크
    if (!$c.stf.checkMaxLength(txb_DIGITAL_SECU_ULY_NM, 200, "기초자산")) return false;
    if (!$c.stf.checkMaxLength(txb_TRST_INST_ISUR_NM, 200, "신탁기관명")) return false;
    if (!$c.stf.checkMaxLength(txb_TRST_CUSTDN_NM, 200, "위탁/보관기관")) return false;
    if (!$c.stf.checkMaxLength(txb_BENF_NMLIST_ADM_AGNT_NM, 200, "수익자명부관리 대행기관")) return false;
    if (!$c.stf.checkMaxLength(txb_DUTY_HD_NM, 100, "의무보유자")) return false;
    if (!$c.stf.checkMaxLength(txb_LIST_APPL_CHRG_NM, 100, "상장신청인 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_LIST_APPL_CHRG_TEL_NO, 40, "상장신청인 담당자 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_TRST_INST_CHRG_NM, 100, "신탁기관 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_TRST_INST_CHRG_TEL_NO, 40, "신탁기관 담당자 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_DESIGN_ADVSER_CHRG_NM, 100, "지정자문인 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_DESIGN_ADVSER_CHRG_TEL_NO, 40, "지정자문인 담당자 연락처")) return false;
    return true;
};

/**
     * @method
     * @name checkDISTRPAY
     * @description 분배금 지급 기준일 필수값 체크
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.checkDISTRPAY = async function() {
    let vCheck = false;
    let componuntName;
    let componuntValue;

    // 분배금형태가 지급이라면
    // 기준일 입력을 확인한다.
    if (cmb_DIGITAL_SECU_DISTR_TP_CD.getValue() === '02') {
        for (let i = 12; i >= 1; i--) {
            componuntName = "cmb_DISTR_PAY_BAS_M" + i;
            componuntValue = document.getElementById(componuntName).getValue();
            if (componuntValue !== "") {
                vCheck = true;
                break;
            }
            if (vCheck === true) {
                break;
            }
        }
        if (vCheck === false) {
            await $c.win.alert("[분배금지급] 지급 기준일을 입력하세요.");
            return false;
        }
    }
    let vMonthId, vDayId;

    // 월+일  값 유효성 체크
    for (let i = 1; i <= 12; i++) {
        vMonthId = "cmb_DISTR_PAY_BAS_M" + i;
        vDayId = "cmb_DISTR_PAY_BAS_D" + i;
        if ((document.getElementById(vMonthId).getValue() !== "") && (document.getElementById(vDayId).getValue() === "")) {
            await $c.win.alert("[분배금지급 지급기준일" + i + "] 일자를 선택해주세요.");
            document.getElementById(vDayId).focus();
            return false;
        } else if ((document.getElementById(vDayId).getValue() !== "") && (document.getElementById(vMonthId).getValue() === "")) {
            await $c.win.alert("[분배금지급 지급기준일" + i + "] 월을 선택해주세요.");
            document.getElementById(vMonthId).focus();
            return false;
        }
    }

    // 중간입력 체크
    // 중간의 값이 하나라도 빌 경우
    // return false; 처리
    vCheck = true;
    // var componuntName;
    // var componuntValue;

    for (let i = 12; i >= 1; i--) {
        componuntName = "cmb_DISTR_PAY_BAS_M" + i;
        componuntValue = document.getElementById(componuntName).getValue();
        if (componuntValue !== "") {
            for (let j = i--; j >= 1; j--) {
                // 빈값이 있다면
                if (document.getElementById("cmb_DISTR_PAY_BAS_M" + j).getValue() === "") {
                    vCheck = false;
                    break;
                }
            }
        }
        if (vCheck === false) {
            break;
        }
    }
    if (vCheck === false) {
        await $c.win.alert("[분배금지급] 기준일을 순서대로 선택해주세요.");
        return false;
    }
    /*
    	for(var i = 12; i >=1; i--){

    		componuntName = "txb_DISTR_PAY_BAS_DD"+i;
    		componuntValue = getObjectValue(document.getElementById(componuntName));
    		if (componuntValue != ""){

    			for(var j = --i ; j>=1; j--){
                    // 빈값이 있다면
    				if (getObjectValue(document.getElementById("txb_DISTR_PAY_BAS_DD"+j)) == componuntValue){
    					vCheck = false;
    					break;
    				}
    			}
    		}
    		if(vCheck == false){
    			break;
    		}
    	}

    	if (vCheck == false){
    		alert("[분배금지급] 기준일이 중복으로 선택되었습니다.");
    		return false;
    	}
     */
    return true;
};

/**
