/**
 * @method
 * @name dISTR
 * @description 분배금지급 vType : 1 : 월 2: 일 vNumber : 기준일
 * @param {*} vType vType
 * @param {*} vNumber vNumber
 * @returns {void}
 * @hidden N
 */
scwin.dISTR = function(vType, vNumber) {
    let vDate = document.getElementById("txb_DISTR_PAY_BAS_DD" + vNumber).getValue(); // 월+일자
    let vMonth = document.getElementById("cmb_DISTR_PAY_BAS_M" + vNumber).getValue(); // 월
    let vDay = document.getElementById("cmb_DISTR_PAY_BAS_D" + vNumber).getValue(); // 일

    if (vDate === "") {
        vDate = "0000";
    }
    if (vMonth === "") {
        vMonth = "00";
    }
    if (vDay === "") {
        vDay = "00";
    }
    if ((vMonth === "00") && (vDay === "00")) {
        // 값이 없을 경우 공백값으로 셋팅
        document.getElementById("txb_DISTR_PAY_BAS_DD" + vNumber).setValue("");
    } else {
        // 값이 있을 경우
        // 값을 textbox로 셋팅하여 해당 textbox에 넣어준다.
        let str = "";
        if (vType === 1) {
            str = vMonth + vDate.substring(2, 4);
        } else {
            str = vDate.substring(0, 2) + vDay;
        }
        document.getElementById("txb_DISTR_PAY_BAS_DD" + vNumber).setValue(str);
    }
};

/**
 * @method
 * @name dISTRCombo
 * @description 분배금지급 ds로 불러온 값을 콤보박스로 setting
 * @returns {void}
 * @hidden N
 */
scwin.dISTRCombo = function() {
    let vDate;
    for (let i = 1; i <= 12; i++) {
        vDate = document.getElementById("txb_DISTR_PAY_BAS_DD" + i).getValue();
        if (vDate !== "") {
            document.getElementById("cmb_DISTR_PAY_BAS_M" + i).setValue(vDate.substring(0, 2));
            document.getElementById("cmb_DISTR_PAY_BAS_D" + i).setValue(vDate.substring(2, 4));
        } else {
            // 값이 없을 경우 공백값으로 셋팅
            document.getElementById("cmb_DISTR_PAY_BAS_M" + i).setValue("");
            document.getElementById("cmb_DISTR_PAY_BAS_D" + i).setValue("");
        }
    }
};
